await write('deliverables/content-migration-review.html', `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>Brooktrails content migration review</title><style>body{margin:0;background:#f4f1e8;color:#15241f;font:16px/1.55 system-ui,sans-serif}.wrap{width:min(1100px,calc(100% - 2rem));margin:auto;padding:3rem 0}h1,h2{font-family:Georgia,serif;line-height:1.05}h1{font-size:clamp(2.5rem,6vw,5rem);max-width:12ch}.meta,.note{padding:1rem 1.2rem;background:#e3ede6;border-left:4px solid #1d735f}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:1rem;margin:2rem 0}.stats div{padding:1rem;background:#123b31;color:white}.stats strong{display:block;font-size:2rem;color:#b9fff1}table{width:100%;border-collapse:collapse;background:white}th,td{padding:.8rem;text-align:left;vertical-align:top;border-bottom:1px solid #d6ddd8}th{background:#123b31;color:white}td code{display:block;overflow-wrap:anywhere}td span{font-size:.82rem;color:#52655e}@media(max-width:720px){table,thead,tbody,tr,th,td{display:block}thead{position:absolute;clip:rect(0 0 0 0)}tr{margin-bottom:1rem;border:1px solid #d6ddd8}td:before{display:block;font-size:.7rem;font-weight:800;text-transform:uppercase;color:#1d735f}td:nth-child(1):before{content:'Original route'}td:nth-child(2):before{content:'Preview destination'}td:nth-child(3):before{content:'Disposition'}}</style></head><body><main class="wrap"><p>Reviewer deliverable · September 30, 2026</p><h1>Brooktrails content migration review</h1><p class="meta">This document separates migration accounting from the resident experience. It records how every route captured from the former public sitemap is handled by the staged preview.</p><div class="stats"><div><strong>${routes.length}</strong>captured source routes</div><div><strong>${publishableDocuments.length}</strong>publishable retained files</div><div><strong>${routes.filter(r=>r.disposition === 'retained-in-archive-separate-fire-site').length}</strong>Fire routes separated</div><div><strong>1</strong>identity-data form withheld</div><div><strong>noindex</strong>preview policy</div></div><h2>Review boundaries</h2><ul><li>The capture date is September 10, 2026.</li><li>Captured statements are migration source material, not proof that changing facts remain current.</li><li>Fire and Other Emergency Services content is absent from district-facing navigation and preserved only in the source archive pending the separate Fire website.</li><li>The legacy construction-meter application requested Social Security and driver’s-license information. Its source record remains in the inventory and Git history, but the file is withheld from the published preview pending current-form review and a secure submission decision.</li><li>Production hosting, DNS, forms, payments, outreach, and district acceptance remain outside this preview.</li></ul><h2>Route disposition</h2><table><thead><tr><th>Original route</th><th>Preview destination</th><th>Disposition</th></tr></thead><tbody>${routeRows}</tbody></table><p class="note">Review outcome should be recorded as accept, revise, hold, or retire. Production migration requires separate scope and authority.</p></main></body></html>`);

await write('deliverables/town-manager-proposal.html', `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>Brooktrails Website Redesign Proposal Brief</title><style>:root{--ink:#10241e;--forest:#123b31;--creek:#2f8f7b;--mint:#dff5ef;--gold:#d79d38;--paper:#f7f3e9;--line:#ccd8d1}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,sans-serif}.wrap{width:min(1120px,calc(100% - 2rem));margin:auto;padding:3rem 0 5rem}h1,h2,h3{font-family:Georgia,serif;line-height:1.08}h1{max-width:14ch;font-size:clamp(2.7rem,7vw,5.5rem);margin:.4rem 0 1rem}h2{margin-top:3rem;font-size:clamp(1.8rem,4vw,3rem)}h3{font-size:1.25rem}.kicker{font-weight:800;letter-spacing:.13em;text-transform:uppercase;color:var(--creek)}.lead{max-width:62rem;font-size:1.2rem}.summary,.privacy{padding:1.4rem 1.6rem;background:var(--mint);border-left:5px solid var(--creek)}.privacy{background:#fff0d6;border-color:var(--gold)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:1rem}.card{padding:1.25rem;background:#fff;border:1px solid var(--line)}.card b{color:var(--creek)}.flow{display:grid;grid-template-columns:repeat(7,minmax(125px,1fr));gap:.65rem;overflow-x:auto;padding-bottom:.5rem}.flow div{position:relative;min-width:125px;padding:1rem;background:var(--forest);color:#fff}.flow span{display:block;color:#b9fff1;font-weight:900}.flow div:not(:last-child)::after{content:'→';position:absolute;right:-.55rem;top:50%;z-index:2;color:var(--gold);font-size:1.25rem}.decision{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1rem}.decision article{padding:1.2rem;border-top:4px solid var(--creek);background:#fff}.why{color:#3f514b}.boundary{margin-top:3rem;padding:1.2rem;border:1px solid var(--line)}a{color:#176654}.meta{color:#52655e}@media print{body{background:#fff}.wrap{width:100%;padding:0}.flow{grid-template-columns:repeat(7,1fr)}a{color:#000}}@media(max-width:720px){.flow{grid-template-columns:1fr}.flow div:not(:last-child)::after{content:'↓';right:1rem;top:auto;bottom:-1.25rem}}</style></head><body><main class="wrap"><p class="kicker">Proposal review brief · Prepared for Town Manager Tamara Alaniz</p><h1>A Brooktrails website built around decisions.</h1><p class="lead">The redesign keeps the redwood character that makes Brooktrails memorable while giving residents, prospective residents, and reviewers short, trustworthy paths to the next useful action.</p><div class="summary"><strong>Proposal outcome</strong><p>Replace a document-first experience with four bounded civic hubs, two high-intent guided journeys, a searchable public library, and a concise District Desk—without implying that the preview is an operating permit, payment, emergency, or records-delivery system.</p></div><h2>What changed—and why</h2><div class="grid"><article class="card"><h3>Four non-overlapping hubs</h3><p>Services, Parks & Places, District & Board, and Discover Brooktrails each own a distinct kind of visit.</p><p class="why"><b>Why:</b> Visitors stop encountering the same destinations under several labels, reducing the feeling that the district has more departments and pages than it actually does.</p></article><article class="card"><h3>Build on My Property</h3><p>A seven-step sequence distinguishes district design review from County permitting and later utility work.</p><p class="why"><b>Why:</b> A resident should know which form starts the process, which agency decides each step, and what approval comes next.</p></article><article class="card"><h3>Considering Brooktrails?</h3><p>A practical orientation brings services, costs, maps, safety, recreation, and jurisdiction into one short decision guide.</p><p class="why"><b>Why:</b> The previous journey sold the landscape but made a prospective resident assemble essential property questions from several unrelated pages.</p></article><article class="card"><h3>Intent-aware search</h3><p>Search recognizes terms such as permit, moving, sewer availability, roads, insurance, and evacuation, and offers recovery when no record matches.</p><p class="why"><b>Why:</b> People search in their own language. A silent blank result can incorrectly suggest that the district has no information.</p></article><article class="card"><h3>Human-readable records</h3><p>Cryptic captured filenames are presented with descriptive titles, categories, dates where known, and a currentness warning.</p><p class="why"><b>Why:</b> Clear labels improve confidence and reduce accidental downloads without rewriting the underlying public record.</p></article><article class="card"><h3>Precise destinations</h3><p>Map, planning, archive, and contact links now retain the visitor’s context rather than falling back to a generic page.</p><p class="why"><b>Why:</b> A link should complete the promise made by its label; generic landings force visitors to restart their search.</p></article></div><h2>The guided building journey</h2><div class="flow" aria-label="Building and permit journey"><div><span>01</span>Confirm parcel and district services</div><div><span>02</span>Prepare plans and site information</div><div><span>03</span>Submit district design review</div><div><span>04</span>Receive written district approval</div><div><span>05</span>Apply for County permits</div><div><span>06</span>Complete access or septic review</div><div><span>07</span>Coordinate utilities and final inspection</div></div><p class="why"><b>Why this order:</b> It prevents a later-stage water-meter application or a County permit page from appearing to be the first step, while making the agency handoff explicit.</p><div class="privacy"><h2>Why the legacy identity-data form was removed</h2><p>The captured construction-meter application requested Social Security and driver’s-license information. Republishing that form in a public preview—and inviting ordinary email submission—would create unnecessary privacy, identity-theft, retention, and records-handling risk. The preview now tells applicants to request the current form and approved delivery method directly from district staff. The source remains recoverable in repository history for authorized review, but it is no longer published or searchable.</p><p><strong>Recommended production decision:</strong> determine whether those fields are still necessary, apply data minimization, and provide a documented secure or in-person intake channel before republishing any equivalent form.</p></div><h2>How the “limited hangout” architecture works</h2><div class="decision"><article><h3>Arrival</h3><p>The homepage offers two urgent journeys and four visually distinct hubs instead of a long sitemap.</p></article><article><h3>Focused choice</h3><p>Each hub reveals only related questions, keeping cognitive load low and curiosity high.</p></article><article><h3>Useful depth</h3><p>Exact forms, records, maps, and official outside agencies appear only when they help complete the selected task.</p></article><article><h3>Human fallback</h3><p>The District Desk remains one step away when the answer is current, property-specific, or sensitive.</p></article></div><h2>What this proposal does not claim</h2><ul><li>The preview is not district acceptance or a production authorization.</li><li>Captured documents do not prove that fees, contacts, policies, or dates remain current.</li><li>The site does not issue permits, receive sensitive applications, process payments, or operate emergency services.</li><li>Production hosting, accessibility acceptance, records ownership, secure forms, analytics, maintenance, and support require a separately approved implementation plan.</li></ul><div class="boundary"><strong>Suggested review decision</strong><p>Approve the information architecture and visual direction; identify a district content owner; confirm current forms and fees; decide secure intake requirements; and scope a controlled production migration.</p><p class="meta">Prepared from the September 10, 2026 public-source capture and the staged, noindex GitHub Pages preview. Current official sources control changing information.</p></div></main></body></html>`);

const contactBody = `<section class="section district-desk-section"><div class="shell"><div class="topic-brief" hidden data-contact-topic aria-live="polite"></div><div class="district-desk-layout"><article class="district-desk-primary"><div><span class="contact-icon">${icon('board')}</span><p class="eyebrow">Township office</p><h2>One desk for district questions.</h2><p>For utilities, planning, public records, Board business, fees, deadlines, trail concerns, or a process that may have changed, start here.</p></div><address class="district-desk-channels"><a class="district-desk-channel" href="tel:+17074592494"><small>Call</small><strong>707-459-2494</strong><span>Talk with the district office →</span></a><a class="district-desk-channel" href="mailto:btcsd@btcsd.org"><small>Email</small><strong>btcsd@btcsd.org</strong><span>Write to the district →</span></a><div class="district-desk-channel"><small>Visit or mail</small><strong>24860 Birch Street</strong><span>Willits, CA 95490</span></div><div class="district-desk-channel"><small>Fax</small><strong>707-459-0358</strong><span>District office fax</span></div></address><div class="secure-contact-note"><strong>Protect sensitive information</strong><p>Do not email Social Security numbers, driver’s-license images, financial-account details, or other identity documents. Ask staff for the approved secure or in-person delivery method.</p></div></article><aside class="district-desk-secondary"><span class="contact-icon">${icon('tree')}</span><p class="eyebrow">Golf course</p><h2>Information & tee times</h2><p>The course keeps its own direct line for current tee times, operating details, and conditions.</p><a class="district-desk-course" href="tel:+17074596761"><small>Call the course</small><strong>707-459-6761</strong><span>Tap to call →</span></a><a class="text-link" href="../parks/#parks-panel-golf">See the golf field file →</a></aside></div></div></section>`;
await write('contact/index.html',page('contact/index.html',{title:'District Desk',description:'Reach the Brooktrails Township district office and golf course from one concise contact hub.',active:null,route:'contact',eyebrow:'District desk',heading:'A person, when a person is the answer.',lede:'The complete district contact directory lives here—kept out of the main trail map, but always one clear step away.',body:contactBody}));

const archiveSections = sourcePages.map(p => `<details id="${sourceId(p.url)}"><summary><span>${escapeHtml(p.title)}</span><small>${escapeHtml(new URL(p.url).pathname || '/')}</small></summary><div><p><a class="text-link" href="${escapeHtml(p.url)}" target="_blank" rel="noopener">Open current source ↗</a></p><pre>${escapeHtml(p.text)}</pre></div></details>`).join('');
const archiveBody = `<section class="section"><div class="shell"><div class="archive-note"><strong>Source snapshot: September 10, 2026</strong><p>This retained text preserves what was publicly rendered across all 30 sitemap pages. Repeated navigation and footer text are intentionally included as source evidence. Current official sources control changing information.</p><div class="inline-links"><a href="../planning/">Current building path →</a><a href="../services/">Current services →</a><a href="../contact/">District Desk →</a></div></div><div class="archive-list">${archiveSections}</div></div></section>`;
await write('archive/index.html',page('archive/index.html',{title:'Retained Source Archive',description:'Text archive of the 30 public btcsd.org sitemap pages captured September 10, 2026.',active:'services',route:'archive',eyebrow:'Retained source archive',heading:'Nothing disappears in the redesign.',lede:'The complete rendered public text remains available for migration review, historical reference, and content parity checks.',body:archiveBody}));

for (const route of routes) {
  const sourcePath = route.sourceRoute === '/' ? '' : route.sourceRoute;
  if (!sourcePath) continue;
  const targetRel = route.destination;
  const aliasRel = `${sourcePath}/index.html`;
  if (aliasRel === targetRel) continue;
  const aliasPrefix = prefixFor(aliasRel);
  const targetHref = `${aliasPrefix}${targetRel.replace('/index.html','/').replace('index.html','')}` || aliasPrefix;
  await write(aliasRel, `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><meta http-equiv="refresh" content="0;url=${escapeHtml(targetHref)}"><title>Page moved | Brooktrails Township</title><link rel="canonical" href="${escapeHtml(targetHref)}"><link rel="stylesheet" href="${aliasPrefix}styles.css?v=20261001-4"></head><body class="page-redirect"><main class="redirect-page"><h1>This information has moved.</h1><p><a class="button" href="${escapeHtml(targetHref)}">Continue to the updated page</a></p></main></body></html>`);
}

await write('404.html', page('404.html',{title:'Page not found',description:'Find Brooktrails Township services and public information.',active:'home',eyebrow:'404',heading:'That trail ends here.',lede:'The page may have moved during the redesign. Use the links below to get back on course.',body:'<section class="section"><div class="shell button-row"><a class="button" href="index.html">Return home</a><a class="button button-outline-dark" href="resources/">Search documents</a></div></section>'}));

console.log(JSON.stringify({pages:11, redirects:routes.filter(r=>r.sourceRoute !== '/' && `${r.sourceRoute}/index.html` !== r.destination).length + 1, districtDocuments:districtDocuments.length, publishableDocuments:publishableDocuments.length, capturedDocumentRecords:documents.length}, null, 2));
